class AuthInterceptor(private val tokens: TokenStore) : Interceptor {
  override fun intercept(chain: Interceptor.Chain): Response {
    val request = chain.request().newBuilder()
      .addHeader("Authorization", "Bearer ${tokens.access.orEmpty()}")
      .build()
    return chain.proceed(request)
  }
}

// 401 refresh belongs in an Authenticator, not an interceptor: OkHttp calls it
// only on an auth challenge and retries the original request for you.
class TokenAuthenticator(private val tokens: TokenStore) : Authenticator {
  override fun authenticate(route: Route?, response: Response): Request? {
    if (response.responseCount() >= 3) return null          // give up, don't loop
    val fresh = runBlocking { tokens.refresh() } ?: return null
    return response.request.newBuilder()
      .header("Authorization", "Bearer $fresh")
      .build()
  }

  private fun Response.responseCount(): Int =
    generateSequence(this) { it.priorResponse }.count()
}

// Network interceptor — sees every round trip, used here to rewrite cache headers
val cacheHeaders = Interceptor { chain ->
  chain.proceed(chain.request()).newBuilder()
    .header("Cache-Control", "public, max-age=60")
    .removeHeader("Pragma")
    .build()
}

val client = OkHttpClient.Builder()
  .addInterceptor(HttpLoggingInterceptor().apply {
    level = HttpLoggingInterceptor.Level.HEADERS
    redactHeader("Authorization")
  })
  .addInterceptor(AuthInterceptor(tokens))
  .authenticator(TokenAuthenticator(tokens))
  .addNetworkInterceptor(cacheHeaders)
  .build()

