// An unknown enum constant must not take the screen down
@Serializable(with = StatusSerializer::class)
enum class Status { Active, Banned, Unknown }

object StatusSerializer : KSerializer<Status> {
  override val descriptor = PrimitiveSerialDescriptor("Status", PrimitiveKind.STRING)
  override fun serialize(encoder: Encoder, value: Status) =
    encoder.encodeString(value.name.lowercase())
  override fun deserialize(decoder: Decoder): Status {
    val raw = decoder.decodeString()
    return Status.entries.firstOrNull { it.name.equals(raw, ignoreCase = true) } ?: Status.Unknown
  }
}

