class LongPollTimeouts : Interceptor {
  override fun intercept(chain: Interceptor.Chain): Response {
    val request = chain.request()
    return if (request.header("X-Long-Poll") != null) {
      chain.withReadTimeout(120, TimeUnit.SECONDS).proceed(request)
    } else {
      chain.proceed(request)
    }
  }
}

// Retry in the repository, where cancellation works. Idempotent calls only.
suspend fun <T> retrying(attempts: Int = 3, block: suspend () -> T): T {
  var wait = 500.milliseconds
  repeat(attempts - 1) {
    try {
      return block()
    } catch (e: IOException) {
      // transient: offline, DNS, timeout
    } catch (e: HttpException) {
      if (e.code() != 429 && e.code() < 500) throw e   // other 4xx will never succeed
    }
    delay(wait + Random.nextInt(0, 250).milliseconds)  // jitter, or everyone returns at once
    wait *= 2
  }
  return block()
}

